    { id: "chest_tal6", n: "Ларец талисманов · первородный", cyc: 6, tier: "product", r: 6, img: "reward-chest-v1.png", team: true, lore: "Один духовный талисман первородной редкости.", src: ["Мастерская · рецепт", "Лутбоксы Кланового босса"] },
    { id: "chest_eq6", n: "Ларец снаряжения · первородный", cyc: 6, tier: "product", r: 6, img: "reward-chest-v1.png", team: true, lore: "Один предмет снаряжения первородной редкости.", src: ["Мастерская · рецепт", "Лутбоксы Арены и Лиги"] }
